const exportAudio={"stop-bright-ding.wav": "data:audio/wav;base64,", "stop-warm-dong.wav": "data:audio/wav;base64,", "reel.wav": "data:audio/wav;base64,", "lever.wav": "data:audio/wav;base64,", "stop-low-ticks.wav": "data:audio/wav;base64,", "stop.wav": "data:audio/wav;base64,", "lever-clear.wav": "data:audio/wav;base64,", "stop-user.mp3": "data:audio/mpeg;base64,"};
(()=>{
 const toggle=document.getElementById('sound-toggle'),test=document.getElementById('sound-test'),hint=document.getElementById('audio-hint');
 let enabled=true;try{enabled=localStorage.getItem('twist-sound')!=='off'}catch{}
 let token=0,active=false,reelPrimed=false,endingTimer=null;
 let endContext=null,endBufferPromise=null,endSource=null;
 const endBytes=Promise.resolve(Uint8Array.from(atob(exportAudio['stop-user.mp3'].split(',')[1]),c=>c.charCodeAt(0)).buffer);endBytes.catch(()=>{});
 function cancelEnding(){clearTimeout(endingTimer);endingTimer=null;if(endSource){endSource.onended=null;try{endSource.stop()}catch{}endSource.disconnect();endSource=null}}
 function prepareEnding(){
  const Context=window.AudioContext||window.webkitAudioContext;
  if(!Context)return Promise.reject(new Error('Audio playback unavailable'));
  if(!endContext)endContext=new Context();
  if(endContext.state!=='running')endContext.resume().catch(()=>{});
  if(!endBufferPromise){endBufferPromise=endBytes.then(bytes=>endContext.decodeAudioData(bytes.slice(0)));endBufferPromise.catch(()=>{endBufferPromise=null})}
  return endBufferPromise;
 }
 async function playEnding(current){
  const buffer=await prepareEnding();
  if(current!==token||!enabled)return;
  if(endContext.state!=='running')await endContext.resume();
  if(current!==token||!enabled)return;
  const source=endContext.createBufferSource();source.buffer=buffer;source.connect(endContext.destination);endSource=source;
  source.onended=()=>{source.disconnect();if(endSource===source){endSource=null;toggle.dataset.audioState=enabled?'idle':'muted'}};
  toggle.dataset.audioState='ending';source.start(0,0);
 }
 const make=(name,volume)=>{const audio=new Audio(exportAudio[name]);audio.preload='auto';audio.volume=volume;audio.setAttribute('playsinline','');audio.className='audio-player';audio.setAttribute('aria-hidden','true');document.body.append(audio);audio.load();return audio};
 const lever=make('lever-clear.wav',.95),reel=make('reel.wav',.8);reel.loop=true;
 const paint=()=>{toggle.textContent=enabled?'Sound: On':'Sound: Off';toggle.setAttribute('aria-pressed',String(enabled));toggle.setAttribute('aria-label',enabled?'Mute sound effects':'Enable sound effects')};paint();
 function reset(audio){audio.pause();try{audio.currentTime=0}catch{}}
 function play(audio){try{return Promise.resolve(audio.play())}catch(error){return Promise.reject(error)}}
 function failed(error,current){if(current!==token||!enabled||error?.name==='AbortError')return;toggle.dataset.audioState='blocked';hint.textContent='Tap the lever again to enable audio.'}
 function primeReel(){if(reelPrimed)return;reel.muted=true;play(reel).then(()=>{reset(reel);reel.muted=false;reelPrimed=true}).catch(()=>{reel.muted=false})}
 function begin(){cancelEnding();const current=++token;active=true;[lever,reel].forEach(reset);reel.loop=true;if(!enabled)return;hint.textContent='';primeReel();prepareEnding().catch(error=>failed(error,current));toggle.dataset.audioState='lever';play(lever).catch(error=>failed(error,current));}
 function spin(){const current=token;if(!enabled||!active)return;reel.loop=true;reel.muted=false;reset(reel);play(reel).then(()=>{if(current===token&&enabled)toggle.dataset.audioState='playing';else reset(reel)}).catch(error=>failed(error,current));}
 function finish(){const current=++token;active=false;reset(reel);cancelEnding();toggle.dataset.audioState=enabled?'waiting':'muted';if(enabled)playEnding(current).catch(error=>failed(error,current));}
 reel.addEventListener('ended',()=>{if(!active){reel.loop=true;toggle.dataset.audioState='idle'}});
 toggle.addEventListener('click',()=>{enabled=!enabled;if(!enabled){cancelEnding();++token;active=false;[lever,reel].forEach(reset);toggle.dataset.audioState='muted';hint.textContent=''}try{localStorage.setItem('twist-sound',enabled?'on':'off')}catch{}paint()});
 test?.addEventListener('click',()=>{cancelEnding();if(!enabled){enabled=true;paint();try{localStorage.setItem('twist-sound','on')}catch{}}const current=++token;active=false;[lever,reel].forEach(reset);reel.loop=false;reel.muted=false;play(reel).then(()=>{reelPrimed=true;toggle.dataset.audioState='testing';hint.textContent=''}).catch(error=>failed(error,current))});
 window.addEventListener('pagehide',()=>{cancelEnding();++token;active=false;[lever,reel].forEach(reset)});
 window.twistSound={begin,spin,finish};
})();
